// The access pages and the tools behind them: /login/, /login/enrol/, /login/step-up/,
// /login/denied/, /tools/, /tools/debug/, /tools/users/,
// /tools/domain/, /tools/page/ (login/**/index.html and
// tools/**/index.html, generated by scripts/pages.ts). #root's data-page
// says which one. Same global styles and service worker start as the home page (src/main.tsx).
import './styles/reset.css'
import './styles/fonts.css'
import './styles/base.css'

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { DebugPage } from './login/DebugPage'
import { DomainPage } from './login/DomainPage'
import { EnrolPage } from './login/EnrolPage'
import { DeniedPage, StepUpPage } from './login/GatePages'
import { LoginPage } from './login/LoginPage'
import { PageReconPage } from './login/PageReconPage'
import { ToolsPage } from './login/ToolsPage'
import { UsersPage } from './login/UsersPage'
import { startServiceWorker } from './telemetry/serviceWorker'

startServiceWorker()

const root = document.getElementById('root')
if (!root) throw new Error('Missing #root element')

const PAGES = {
  login: LoginPage,
  enrol: EnrolPage,
  stepup: StepUpPage,
  denied: DeniedPage,
  tools: ToolsPage,
  debug: DebugPage,
  users: UsersPage,
  domain: DomainPage,
  page: PageReconPage,
}
const Page = PAGES[root.dataset.page as keyof typeof PAGES] ?? LoginPage

createRoot(root).render(
  <StrictMode>
    <Page />
  </StrictMode>,
)
